```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

/// Upper bound on the question length, in characters (Python `len` semantics).
const MAX_QUESTION_CHARS: usize = 512;

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;

        // `requires` guarantees the input is already within the bound; the
        // truncation enforces the `ensures` bound on the output regardless.
        let question: String = query
            .query
            .question
            .chars()
            .take(MAX_QUESTION_CHARS)
            .collect();

        // The only authority this node holds is the read-only knowledge base.
        let knowledge: Vec<String> = kb_read::lookup(&question);

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

